    public function place(string $cartKey,array $input,int $freeShippingThresholdCents,bool $freeShippingEnabled): array
    {
        $contact=['first_name'=>trim((string)($input['first_name']??'')),'last_name'=>trim((string)($input['last_name']??'')),'email'=>strtolower(trim((string)($input['email']??''))),'phone'=>trim((string)($input['phone']??''))];
        $address=['recipient_name'=>trim((string)($input['recipient_name']??'')),'phone'=>$contact['phone'],'country_code'=>'BG','city'=>trim((string)($input['city']??'')),'postal_code'=>trim((string)($input['postal_code']??'')),'address_line1'=>trim((string)($input['address_line1']??'')),'address_line2'=>trim((string)($input['address_line2']??''))];
