        if($contact['first_name']===''||mb_strlen($contact['first_name'])>100||$contact['last_name']===''||mb_strlen($contact['last_name'])>100)return $this->error('Попълнете име и фамилия (до 100 знака).',422);
        if(!filter_var($contact['email'],FILTER_VALIDATE_EMAIL)||mb_strlen($contact['email'])>254)return $this->error('Въведете валиден имейл адрес.',422);
        if(!preg_match('/^\+?[0-9 ()\-.]{5,32}$/D',$contact['phone']))return $this->error('Въведете валиден телефонен номер.',422);
        if(mb_strlen($address['recipient_name'])>160||$address['city']===''||mb_strlen($address['city'])>100||mb_strlen($address['postal_code'])>20||$address['address_line1']===''||mb_strlen($address['address_line1'])>200||mb_strlen($address['address_line2'])>200)return $this->error('Попълнете валиден адрес за доставка.',422);
        if(mb_strlen($note)>4000)return $this->error('Бележката може да съдържа до 4000 знака.',422);
        if(($input['accept_terms']??'')!=='1')return $this->error('Потвърдете, че сте прегледали данните за поръчката.',422);
        if(!preg_match('/^[a-f0-9]{64}$/D',$idempotency))return $this->error('Формулярът е изтекъл. Обновете страницата и опитайте отново.',419);
        if($address['recipient_name']==='')$address['recipient_name']=trim($contact['first_name'].' '.$contact['last_name']);
        $requestHash=hash('sha256',json_encode([$contact,$address,$note],JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR));$idempotencyHash=hash('sha256',$idempotency);
        $existing=$this->existingOrder($idempotencyHash);if($existing)return hash_equals($existing['idempotency_hash'],$requestHash)?['ok'=>true,'order_number'=>$existing['order_number'],'free_shipping'=>$existing['shipping_method']==='Куриер до адрес']:$this->error('Тази заявка вече е използвана с други данни.',409);
        $cartId=$this->repository->cartId($cartKey);if($cartId===null)return $this->error('Количката е празна. Добавете продукти, за да продължите.',409);
        $copiedFiles=[];$this->pendingFiles=[];
        $this->db->beginTransaction();
        try{
            $cartLock=$this->db->prepare("SELECT id FROM carts WHERE id=? AND status='active' FOR UPDATE");$cartLock->execute([$cartId]);if(!$cartLock->fetchColumn())return $this->rollbackError('Количката вече е обработена. Обновете страницата.',409);
            $existing=$this->existingOrder($idempotencyHash,true);if($existing){$this->db->rollBack();return hash_equals($existing['idempotency_hash'],$requestHash)?['ok'=>true,'order_number'=>$existing['order_number'],'free_shipping'=>$existing['shipping_method']==='Куриер до адрес']:$this->error('Тази заявка вече е използвана с други данни.',409);}
