            $rows=$this->repository->itemRows($cartId);$rowById=[];foreach($rows as $row)$rowById[(int)$row['id']]=$row;$checkoutItems=$summary['items'];usort($checkoutItems,static fn(array $left,array $right):int=>[(int)$left['product_id'],(int)($left['product_variant_id']??0)]<=>[(int)$right['product_id'],(int)($right['product_variant_id']??0)]);$cartUploadReferences=array_column($this->repository->uploads($cartId),'file_reference');
            $subtotal=0;$shipping=0;$shippingMethod='Куриер до адрес (цената на доставката се уточнява)';$freeShipping=false;
