            $order->execute([$orderNumber,$idempotencyHash,$requestHash,$contact['email'],$contact['phone'],$contact['first_name'],$contact['last_name'],'new','unpaid','unfulfilled','cash_on_delivery',$shippingMethod,'EUR',ProductPricingService::formatCents($subtotal),'0.00',ProductPricingService::formatCents($shipping),'0.00',ProductPricingService::formatCents($subtotal+$shipping),$note===''?null:$note]);
            $orderId=(int)$this->db->lastInsertId();
            $addressInsert=$this->db->prepare("INSERT INTO order_addresses (order_id,address_type,recipient_name,phone,country_code,city,postal_code,address_line1,address_line2) VALUES (?,'shipping',?,?,?,?,?,?,?)");$addressInsert->execute([$orderId,$address['recipient_name'],$address['phone'],'BG',$address['city'],$address['postal_code']?:null,$address['address_line1'],$address['address_line2']?:null]);
            $itemInsert=$this->db->prepare('INSERT INTO order_items (order_id,product_id,product_variant_id,product_name,sku,variant_name,quantity,unit_price,customization_total,discount_total,line_total) VALUES (?,?,?,?,?,?,?,?,?,?,?)');
            $customInsert=$this->db->prepare('INSERT INTO order_item_customizations (order_item_id,field_identifier,field_label,field_type,value_text,file_reference,price_adjustment) VALUES (?,?,?,?,?,?,?)');$stock=[];
            foreach($checkoutItems as $item){$cartRow=$rowById[(int)$item['id']]??null;if(!$cartRow)return $this->rollbackError('Количката е променена. Обновете страницата и опитайте отново.',409);$productId=(int)$item['product_id'];$variantId=$item['product_variant_id']===null?null:(int)$item['product_variant_id'];$product=$this->lockProduct($productId);if(!$product||$product['status']!=='active'||$product['deleted_at']!==null)return $this->rollbackError('Един от продуктите вече не е наличен.',409);
