                $inventory=$variant??$product;$quantity=(int)$item['quantity'];if(!(int)$inventory['is_available']||($inventory['inventory_mode']==='tracked'&&(int)$inventory['stock_quantity']<$quantity))return $this->rollbackError('Няма достатъчна наличност за един от продуктите.',409);
                $customInput=[];foreach($cartRow['customizations'] as $custom)if($custom['customization_field_id']!==null)$customInput[]=['field_id'=>(int)$custom['customization_field_id'],'value'=>$custom['value_text'],'file_reference'=>$custom['file_reference']];$validated=ProductCustomizationValidator::validate($this->db,$productId,$customInput,function(string $reference,array $field)use($cartId,$productId,$cartRow):bool{return $this->repository->uploadOwned($cartId,$productId,(int)$field['id'],$reference,(int)$cartRow['id'])!==null&&$this->files->path($reference)!==null;},$cartRow['fields']);if(!$validated['ok'])return $this->rollbackError($validated['message'],(int)$validated['status']);$customRows=$validated['customizations'];$customPerUnit=array_sum(array_column($customRows,'price_cents'));$baseUnit=ProductPricingService::unitPrice($product,$variant);if($baseUnit===null)return $this->rollbackError('Цената на един от продуктите вече не е валидна.',409);$unitTotal=$baseUnit+$customPerUnit;$subtotal+=$unitTotal*$quantity;if($subtotal>999999999999)return $this->rollbackError('Сумата на поръчката надвишава допустимия размер.',422);$lineTotal=$unitTotal*$quantity;$this->repository->updatePrice((int)$cartRow['id'],ProductPricingService::formatCents($unitTotal));
                    $itemInsert->execute([$orderId,$productId,$variantId,(string)$product['name'],$variant['sku']??$product['sku'],$variant['name']??null,$quantity,ProductPricingService::formatCents($baseUnit),ProductPricingService::formatCents($customPerUnit*$quantity),'0.00',ProductPricingService::formatCents($lineTotal)]);$orderItemId=(int)$this->db->lastInsertId();
                foreach($customRows as $custom){$type=(string)$custom['type'];if($type==='radio')$type='select';$reference=$custom['file_reference']?:null;if($reference!==null){$source=$this->files->path((string)$reference);$target=$this->orderFilesDirectory().DIRECTORY_SEPARATOR.basename((string)$reference);if(!$source||!$this->copyOrderFile($source,$target))return $this->rollbackError('Файл за персонализация не може да бъде прехвърлен. Опитайте отново.',500);$copiedFiles[]=$target;$this->pendingFiles[]=$target;}
                    $customInsert->execute([$orderItemId,(string)$custom['identifier'],(string)$custom['label'],$type,(string)($custom['value']??''),$reference,ProductPricingService::formatCents((int)$custom['price_cents'])]);}
                if($inventory['inventory_mode']==='tracked'){$key=$variantId===null?'p:'.$productId:'v:'.$variantId;$stock[$key]=['product_id'=>$productId,'variant_id'=>$variantId,'entity_id'=>$variantId??$productId,'quantity'=>($stock[$key]['quantity']??0)+$quantity];}
            }
            $expectedSubtotal=filter_var($input['expected_subtotal_cents']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>0]]);if($expectedSubtotal===false||(int)$expectedSubtotal!==$subtotal)return $this->rollbackError('Цената на продукт се е променила. Прегледайте обновената сума и потвърдете поръчката отново.',409);
            $freeShipping=$freeShippingEnabled&&$freeShippingThresholdCents>0&&$subtotal>=$freeShippingThresholdCents;if($freeShipping)$shippingMethod='Куриер до адрес';$this->db->prepare('UPDATE orders SET subtotal=?,shipping_total=?,grand_total=?,shipping_method=? WHERE id=?')->execute([ProductPricingService::formatCents($subtotal),ProductPricingService::formatCents($shipping),ProductPricingService::formatCents($subtotal+$shipping),$shippingMethod,$orderId]);
            foreach($stock as $movement){$table=$movement['variant_id']===null?'products':'product_variants';$lock=$this->db->prepare('SELECT stock_quantity FROM '.$table.' WHERE id=? FOR UPDATE');$lock->execute([$movement['entity_id']]);$available=$lock->fetchColumn();if($available===false||$available===null||(int)$available<$movement['quantity'])return $this->rollbackError('Няма достатъчна наличност за един от продуктите.',409);$after=(int)$available-$movement['quantity'];$this->db->prepare('UPDATE '.$table.' SET stock_quantity=?,is_available=? WHERE id=?')->execute([$after,(int)($after>0),$movement['entity_id']]);$this->db->prepare('INSERT INTO product_stock_movements (product_id,variant_id,quantity_delta,quantity_after,reason,note,admin_id) VALUES (?,?,?,?,?,?,NULL)')->execute([$movement['product_id'],$movement['variant_id'],-$movement['quantity'],$after,'order_created','Поръчка '.$orderNumber]);}
            $this->db->prepare("INSERT INTO order_status_history (order_id,previous_status,new_status,changed_by_admin_id,note) VALUES (?,NULL,'new',NULL,'Поръчката е създадена от клиента.')")->execute([$orderId]);$this->db->prepare('DELETE FROM cart_items WHERE cart_id=?')->execute([$cartId]);$this->db->prepare('DELETE FROM cart_uploads WHERE cart_id=?')->execute([$cartId]);$this->db->prepare("UPDATE carts SET status='converted',guest_key_hash=NULL WHERE id=? AND status='active'")->execute([$cartId]);$this->db->commit();$this->files->delete($cartUploadReferences);$this->pendingFiles=[];return ['ok'=>true,'order_number'=>$orderNumber,'free_shipping'=>$freeShipping];
