    private function lockProduct(int $id): ?array{$q=$this->db->prepare('SELECT id,name,sku,price,sale_price,status,deleted_at,inventory_mode,stock_quantity,is_available FROM products WHERE id=? FOR UPDATE');$q->execute([$id]);$row=$q->fetch(PDO::FETCH_ASSOC);return $row?:null;}
    private function lockVariant(int $id,int $productId): ?array{$q=$this->db->prepare('SELECT id,product_id,name,sku,price,price_adjustment,is_active,is_available,inventory_mode,stock_quantity FROM product_variants WHERE id=? AND product_id=? FOR UPDATE');$q->execute([$id,$productId]);$row=$q->fetch(PDO::FETCH_ASSOC);return $row?:null;}
    private function existingOrder(string $key,bool $lock=false): ?array{$q=$this->db->prepare('SELECT order_number,idempotency_hash,shipping_method FROM orders WHERE idempotency_key=?'.($lock?' FOR UPDATE':''));$q->execute([$key]);$row=$q->fetch(PDO::FETCH_ASSOC);return $row?:null;}
    private function orderFilesDirectory(): string{return rtrim($this->projectRoot,DIRECTORY_SEPARATOR).DIRECTORY_SEPARATOR.'storage'.DIRECTORY_SEPARATOR.'private'.DIRECTORY_SEPARATOR.'order-customizations';}
    private function copyOrderFile(string $source,string $target): bool{$directory=dirname($target);if(!is_dir($directory)&&!mkdir($directory,0750,true)&&!is_dir($directory))return false;if(!copy($source,$target))return false;@chmod($target,0640);return true;}
    private function rollbackError(string $message,int $status): array{if($this->db->inTransaction())$this->db->rollBack();foreach($this->pendingFiles as $path)if(is_file($path))@unlink($path);$this->pendingFiles=[];return $this->error($message,$status);}
    private function error(string $message,int $status): array{return ['ok'=>false,'message'=>$message,'status'=>$status];}
